<script setup>
import { ref } from 'vue'
import { RouterLink, useRouter } from 'vue-router'
import api from '../api'
const router=useRouter(),sidebarOpen=ref(false),itemStatus=ref('found'),itemName=ref(''),category=ref('Electronics'),location=ref(''),dateFound=ref(''),description=ref(''),securityQuestion=ref(''),previewImage=ref(null),selectedFile=ref(null),isLoading=ref(false),errorMessage=ref('')
const onFileSelected=(event)=>{const file=event.target.files[0];if(file){selectedFile.value=file;const reader=new FileReader();reader.onload=(e)=>previewImage.value=e.target.result;reader.readAsDataURL(file)}}
const onSubmit=async()=>{if(!itemName.value||!location.value||!dateFound.value||!securityQuestion.value){errorMessage.value='Please fill in all required fields.';return}isLoading.value=true;errorMessage.value='';const formData=new FormData();formData.append('title',itemName.value);formData.append('category',category.value);formData.append('status',itemStatus.value);formData.append('location',location.value);formData.append('date_found',dateFound.value);formData.append('description',description.value);formData.append('security_question',securityQuestion.value);if(selectedFile.value)formData.append('image',selectedFile.value);try{await api.post('/items',formData);alert('Item posted successfully!');router.push('/lost-and-found')}catch(error){errorMessage.value=error.response?.data?.message||'Failed to post item. Please try again.'}finally{isLoading.value=false}}
</script>
<template><div class="pi-wrapper"><div v-if="sidebarOpen" class="overlay" @click="sidebarOpen=false"></div><div class="sidebar" :class="{open:sidebarOpen}"><div class="sidebar-top"><div class="sidebar-brand"><div class="sidebar-logo">⌂</div><div><p class="sidebar-title">LDCU iFound</p><p class="sidebar-sub">Lost &amp; Found System</p></div></div><button class="close-btn" @click="sidebarOpen=false">✕</button></div><nav class="sidebar-nav"><RouterLink to="/dashboard" class="nav-item">Dashboard</RouterLink><RouterLink to="/lost-and-found" class="nav-item">Lost &amp; Found</RouterLink><RouterLink to="/claims" class="nav-item">Claims Management</RouterLink><RouterLink to="/history" class="nav-item">Claimed History</RouterLink><RouterLink to="/messages" class="nav-item">Messages</RouterLink><RouterLink to="/post-item" class="nav-item active">Post Item</RouterLink><RouterLink to="/profile" class="nav-item">My Profile</RouterLink></nav><div class="sidebar-footer">© 2025 LDCU iFound System</div></div><div class="main"><div class="topbar"><button class="menu-btn" @click="sidebarOpen=!sidebarOpen">☰</button><div class="topbar-brand"><div class="topbar-logo">⌂</div><div><p class="topbar-name">LDCU iFound</p><p class="topbar-sub">Lost &amp; Found System</p></div></div></div><div class="hero-banner">⌂<div><h2>Create New Listing</h2><p>Help reunite lost items with their owners</p></div></div><div class="form-container"><div class="form-card"><div class="card-header">Upload Item Photo</div><div class="upload-area"><template v-if="!previewImage"><p class="upload-title">Drop your photo here</p><label class="btn-choose">Choose Photo<input type="file" accept="image/*" @change="onFileSelected" hidden/></label><p class="upload-hint">JPG, PNG up to 5MB</p></template><template v-else><img :src="previewImage" class="preview-img"/><label class="btn-choose">Change Photo<input type="file" accept="image/*" @change="onFileSelected" hidden/></label></template></div></div><div class="form-card"><div class="card-header blue">Item Details</div><div class="card-body"><div class="fg"><label>Item Status *</label><div class="status-toggle"><button type="button" class="status-btn" :class="{'lost-active':itemStatus==='lost'}" @click="itemStatus='lost'">Lost</button><button type="button" class="status-btn" :class="{'found-active':itemStatus==='found'}" @click="itemStatus='found'">Found</button></div></div><div class="fg"><label>Item Name *</label><input v-model="itemName" placeholder="e.g., iPhone 13 Pro, Black Backpack"/></div><div class="fg"><label>Category *</label><select v-model="category"><option>Electronics</option><option>Documents</option><option>Personal Items</option><option>Clothing</option><option>Others</option></select></div><div class="form-row"><div class="fg"><label>Location Found</label><input v-model="location" placeholder="e.g., Library 3rd Floor"/></div><div class="fg"><label>Date Found</label><input v-model="dateFound" type="date"/></div></div><div class="fg"><label>Item Description</label><textarea v-model="description" rows="5"></textarea></div></div></div><div class="form-card verify-card"><div class="card-header blue">Ownership Verification</div><div class="card-body"><p class="verify-desc">Create a security question that only the true owner can answer.</p><div class="examples-box"><p class="examples-title">Examples:</p><ul><li>"What color is the wallet?"</li><li>"What brand is the phone case?"</li></ul></div><div class="fg"><label>Set a Security Question *</label><input v-model="securityQuestion" placeholder="e.g., What color is the wallet?"/></div></div></div><div v-if="errorMessage" class="error-msg">{{errorMessage}}</div><button class="btn-post" :disabled="isLoading" @click="onSubmit">{{isLoading?'Posting...':'Post Now'}}</button><p class="post-hint">Your post will be visible to the community immediately</p><RouterLink to="/lost-and-found" class="btn-cancel">Cancel</RouterLink></div></div></div></template>
