;font-weight:700}.card-header.blue{background:#1a3c8f}.card-body{padding:24px;display:flex;flex-direction:column;gap:18px}.upload-area{padding:40px 24px;text-align:center;border:2px dashed #d0daf5;border-radius:12px;margin:16px;background:#f8faff}.upload-title{font-weight:700;margin-bottom:16px}.upload-hint{color:#aaa;margin-top:10px}.btn-choose{display:inline-block;background:#1a3c8f;color:#fff;padding:11px 24px;border-radius:10px;cursor:pointer}.preview-img{width:100%;max-height:280px;object-fit:cover;border-radius:10px}.fg{display:flex;flex-direction:column;gap:6px}.fg label{font-size:.88rem;font-weight:700;color:#333}.fg input,.fg textarea,.fg select{padding:12px 16px;border:1.5px solid #dde1e9;border-radius:10px;font-size:.9rem;background:#fff;width:100%}.form-row{display:grid;grid-template-columns:1fr 1fr;gap:16px}.verify-desc{color:#555;line-height:1.6}.examples-box{background:#f0f6ff;border:1px solid #c7d9f5;border-radius:10px;padding:14px 16px}.examples-title{font-weight:700;color:#1a3c8f}.examples-box ul{padding-left:20px}.status-toggle{display:grid;grid-template-columns:1fr 1fr;border:1.5px solid #dde1e9;border-radius:10px;overflow:hidden}.status-btn{padding:14px;border:0;background:#fff;cursor:pointer}.lost-active{background:#ef4444;color:#fff}.found-active{background:#22c55e;color:#fff}.error-msg{background:#fee2e2;color:#dc2626;padding:10px 14px;border-radius:8px}.btn-post{width:100%;padding:16px;background:#1a3c8f;color:#fff;border:0;border-radius:12px;font-weight:700;cursor:pointer}.btn-post:disabled{background:#ccc}.post-hint{text-align:center;color:#888}.btn-cancel{display:block;text-align:center;padding:14px;background:#fff;color:#333;border:1.5px solid #dde1e9;border-radius:12px;text-decoration:none}@media(max-width:600px){.form-container{padding:16px}.form-row{grid-template-columns:1fr}}
</style>